import EventEmitter from 'eventemitter3';
import { DeviceInfo } from './device-info';
import { DeviceType } from './device-info/device-type';
import { KeyboardEvents } from './types';

export class VirtualKeyboard extends EventEmitter<KeyboardEvents> {

    public readonly resizesWindowWhenOpen: boolean;

    private lastActiveElement: HTMLElement | null;
    private mHeight: number = 0;
    private mIsOpen: boolean = false;

    public set height(height: number) {
        height = Math.max(0, height);
        if (this.mHeight !== height) {
            this.mHeight = height;
            this.emit('heightChanged', this.mHeight);
        }
    }

    public get height(): number {
        return this.mHeight;
    }

    public get isOpen(): boolean {
        return this.mIsOpen;
    }

    public set isOpen(isOpen: boolean) {
        if (this.mIsOpen !== isOpen) {
            this.mIsOpen = isOpen;
            this.blurLastActiveElement();
            if (!this.isOpen) {
                this.height = 0;
            }
            this.emit('isOpen', this.isOpen);
        }
    }

    public constructor(deviceType: DeviceType, deviceInfo: DeviceInfo, freezePageDimensions: boolean) {
        super();
        const { isDesktop } = deviceType;
        this.mIsOpen = false;
        this.lastActiveElement = null;
        this.onBlur = this.onBlur.bind(this);
        if (isDesktop) {
            this.resizesWindowWhenOpen = false;
        } else {
            this.resizesWindowWhenOpen = freezePageDimensions;
        }

        if (!isDesktop) {
            this.setupWebEvents();
        }
    }

    private removeLastActiveElementBlurListener() {
        if (this.lastActiveElement) {
            this.lastActiveElement.removeEventListener('blur', this.onBlur);
            this.lastActiveElement = null;
        }
    }

    private blurLastActiveElement() {
        if (this.lastActiveElement) {
            this.lastActiveElement.blur();
        }
    }

    private setupWebEvents() {
        document.addEventListener('focus', () => {
            if (document.activeElement && document.activeElement.tagName === 'INPUT') {
                this.isOpen = true;
                this.lastActiveElement = document.activeElement as HTMLElement;
                this.lastActiveElement.addEventListener('blur', this.onBlur, false);
            }
        }, true);
    }

    private onBlur(e: FocusEvent) {
        if (e.relatedTarget === null) {
            this.removeLastActiveElementBlurListener();
            this.isOpen = false;
        }
    }
}